1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { CATALOG } from "../lib/catalog";
4	import { CATEGORIES, QUESTIONS } from "../lib/questions";
5	import {
6	  recommend,
7	  recommendationToMarkdown,
8	  recommendationToText,
9	  scaffoldCommands,
10	} from "../lib/engine";
11	import { DETAILS } from "../lib/details";
12	import { decodeState, encodeState } from "../lib/share";
13	import type { Answers, CategoryId } from "../lib/types";
14	
15	function firstAnswers(catId: CategoryId): Answers {
16	  const a: Answers = {};
17	  for (const q of QUESTIONS) {
18	    if (q.appliesTo === "all" || q.appliesTo.includes(catId)) {
19	      a[q.id] = q.options[0].id;
20	    }
21	  }
22	  return a;
23	}
24	
25	const layerPick = (cat: CategoryId, a: Answers, layerLabel: string) =>
26	  recommend(cat, a).layers.find((l) => l.layer === layerLabel)?.primary.name;
27	
28	test("every category produces a complete recommendation", () => {
29	  for (const cat of CATEGORIES) {
30	    const rec = recommend(cat.id, firstAnswers(cat.id));
31	    assert.ok(rec.layers.length > 0, `${cat.id} should have layers`);
32	    for (const layer of rec.layers) {
33	      assert.ok(layer.primary.name, `${cat.id}/${layer.layer} primary name`);
34	      assert.ok(layer.primary.reasons.length > 0, `${cat.id}/${layer.layer} reasons`);
35	      for (const alt of layer.alternatives) {
36	        assert.notEqual(alt.name, layer.primary.name, "alt must differ from primary");
37	      }
38	    }
39	  }
40	});
41	
42	test("all candidate ids exist in the catalog", () => {
43	  for (const cat of CATEGORIES) {
44	    for (const layer of cat.layers) {
45	      for (const c of layer.candidates) {
46	        assert.ok(CATALOG[c.tech], `missing catalog entry: ${c.tech}`);
47	      }
48	    }
49	  }
50	});
51	
52	test("every catalog tech has reference details", () => {
53	  for (const id of Object.keys(CATALOG)) {
54	    assert.ok(DETAILS[id], `missing details: ${id}`);
55	    assert.ok(DETAILS[id].pros.length >= 1, `pros for ${id}`);
56	    assert.ok(DETAILS[id].cons.length >= 1, `cons for ${id}`);
57	  }
58	});
59	
60	test("known scenarios resolve correctly", () => {
61	  const base: Answers = {
62	    experience: "jsts",
63	    scale: "growth",
64	    team: "small",
65	    priority: "speed",
66	    budget: "min",
67	  };
68	  assert.equal(
69	    layerPick("game", { ...base, gameDim: "3d", gamePlatform: "web" }, "Engine"),
70	    "Babylon.js",
71	  );
72	  assert.equal(
73	    layerPick("web", { ...base, webRender: "app", realtime: "no", priority: "scale" }, "Authentication"),
74	    "Better Auth",
75	  );
76	  assert.equal(
77	    layerPick(
78	      "ai",
79	      { ...base, experience: "python", aiKind: "rag", aiHost: "hosted", aiData: "yes" },
80	      "AI framework",
81	    ),
82	    "LlamaIndex",
83	  );
84	  assert.equal(
