1	/**
2	 * Exhaustive deterministic audit of the recommendation engine.
3	 * Runs every relevant answer combination through every category and checks
4	 * invariants. Run with: npx --yes tsx scripts/audit.mts
5	 */
6	import { CATALOG } from "../lib/catalog";
7	import { CATEGORIES, QUESTIONS } from "../lib/questions";
8	import { recommend } from "../lib/engine";
9	import type { Answers, CategoryId } from "../lib/types";
10	
11	let problems = 0;
12	const fail = (msg: string) => {
13	  problems++;
14	  console.log("  ✗ " + msg);
15	};
16	
17	/* ---- Static check: every candidate tech id exists in the catalog ---- */
18	console.log("\n[1] Static: candidate ids exist in CATALOG");
19	for (const cat of CATEGORIES) {
20	  for (const layer of cat.layers) {
21	    for (const cand of layer.candidates) {
22	      if (!CATALOG[cand.tech]) {
23	        fail(`${cat.id}/${layer.label}: candidate "${cand.tech}" missing from CATALOG`);
24	      }
25	    }
26	  }
27	}
28	if (problems === 0) console.log("  ✓ all candidate ids resolve");
29	
30	/* ---- Build the answer space for a category ---- */
31	function questionsFor(catId: CategoryId) {
32	  return QUESTIONS.filter((q) => q.appliesTo === "all" || q.appliesTo.includes(catId));
33	}
34	
35	function* combos(catId: CategoryId): Generator<Answers> {
36	  const qs = questionsFor(catId);
37	  const idx = qs.map(() => 0);
38	  while (true) {
39	    const a: Answers = {};
40	    qs.forEach((q, i) => (a[q.id] = q.options[idx[i]].id));
41	    yield a;
42	    // increment odometer
43	    let k = qs.length - 1;
44	    while (k >= 0) {
45	      idx[k]++;
46	      if (idx[k] < qs[k].options.length) break;
47	      idx[k] = 0;
48	      k--;
49	    }
50	    if (k < 0) break;
51	  }
52	}
53	
54	/* ---- Exhaustive run with per-combo invariants ---- */
55	console.log("\n[2] Exhaustive run: per-combo invariants");
56	const startProblems = problems;
57	
58	// Track, per category+layer, which techs ever win and whether winners ever
59	// had a real (non-generic) reason.
60	const winners = new Map<string, Set<string>>(); // key cat/layer -> tech names
61	const everyReasonGeneric = new Map<string, boolean>(); // key cat/layer -> true until a real reason seen
62	const distinctStacks = new Map<CategoryId, Set<string>>();
63	
64	const GENERIC = "A strong general-purpose choice for this layer";
65	
66	let totalCombos = 0;
67	for (const cat of CATEGORIES) {
68	  distinctStacks.set(cat.id, new Set());
69	  for (const a of combos(cat.id)) {
70	    totalCombos++;
71	    let rec;
72	    try {
73	      rec = recommend(cat.id, a);
74	    } catch (e) {
75	      fail(`${cat.id}: recommend() threw for ${JSON.stringify(a)} -> ${String(e)}`);
76	      continue;
77	    }
78	    const stackKey = rec.summary.map((s) => s.tech).join(" | ");
79	    distinctStacks.get(cat.id)!.add(stackKey);
80	
81	    for (const layer of rec.layers) {
82	      const key = `${cat.id} / ${layer.layer}`;
83	      if (!winners.has(key)) winners.set(key, new Set());
84	      winners.get(key)!.add(layer.primary.name);
85	
86	      // primary must differ from every alternative
87	      for (const alt of layer.alternatives) {
88	        if (alt.name === layer.primary.name) {
89	          fail(`${key}: alternative equals primary (${layer.primary.name})`);
90	        }
91	      }
92	      // primary must have a name and at least one reason
93	      if (!layer.primary.name) fail(`${key}: empty primary name`);
94	      if (layer.primary.reasons.length === 0) fail(`${key}: no reasons`);
95	
96	      const hasReal = layer.primary.reasons.some((r) => r !== GENERIC);
97	      if (!everyReasonGeneric.has(key)) everyReasonGeneric.set(key, true);
98	      if (hasReal) everyReasonGeneric.set(key, false);
99	    }
100	  }
101	}
102	console.log(`  ran ${totalCombos} combinations`);
103	if (problems === startProblems) console.log("  ✓ no per-combo invariant violations");
104	
105	/* ---- Report: layers whose winner reason is ALWAYS generic ---- */
106	console.log("\n[3] Warning: layers where the winner never has a specific reason");
107	let genericLayers = 0;
108	for (const [key, alwaysGeneric] of everyReasonGeneric) {
109	  if (alwaysGeneric) {
110	    genericLayers++;
111	    console.log(`  • ${key} (winner always shows the generic reason)`);
112	  }
113	}
114	if (genericLayers === 0) console.log("  ✓ none");
115	
116	/* ---- Report: candidates that can NEVER win their layer ---- */
117	console.log("\n[4] Info: candidates that never win in any combination");
118	let neverWin = 0;
119	for (const cat of CATEGORIES) {
120	  for (const layer of cat.layers) {
121	    const key = `${cat.id} / ${layer.label}`;
122	    const won = winners.get(key) ?? new Set();
123	    for (const cand of layer.candidates) {
124	      const name = CATALOG[cand.tech]?.name;
125	      if (name && !won.has(name)) {
126	        neverWin++;
127	        console.log(`  • ${key}: "${name}" never wins (only offered as alternative at best)`);
128	      }
129	    }
130	  }
131	}
132	if (neverWin === 0) console.log("  ✓ every candidate wins for some input");
133	
134	/* ---- Report: does the recommendation actually vary per category? ---- */
135	console.log("\n[5] Info: distinct stacks produced per category");
136	for (const cat of CATEGORIES) {
137	  console.log(`  • ${cat.id}: ${distinctStacks.get(cat.id)!.size} distinct stacks`);
138	}
139	
140	/* ---- Targeted scenario assertions (the issues fixed after review) ---- */
141	console.log("\n[6] Targeted scenarios");
142	const base = { experience: "jsts", scale: "growth", team: "small", priority: "speed", budget: "min" };
143	function pick(catId: CategoryId, a: Answers, layerLabel: string) {
144	  const rec = recommend(catId, a);
145	  return rec.layers.find((l) => l.layer === layerLabel)?.primary.name;
146	}
147	function expect(label: string, got: string | undefined, want: string) {
148	  if (got === want) console.log(`  ✓ ${label} -> ${got}`);
149	  else fail(`${label}: expected "${want}", got "${got}"`);
150	}
151	// 3D web game must NOT be Phaser (2D-only)
152	expect(
153	  "game web+3d engine",
154	  pick("game", { ...base, gameDim: "3d", gamePlatform: "web" }, "Engine"),
155	  "Babylon.js",
156	);
157	// 2D web game stays Phaser
158	expect(
159	  "game web+2d engine",
160	  pick("game", { ...base, gameDim: "2d", gamePlatform: "web" }, "Engine"),
161	  "Phaser",
162	);
163	// Flutter (cross + performance) build must not be Expo EAS
164	expect(
165	  "mobile flutter build",
166	  pick("mobile", { ...base, platforms: "cross", priority: "performance", mobileOffline: "no" }, "Build & distribution"),
167	  "Codemagic",
168	);
169	// Cross + RN (not performance) build is Expo EAS
170	expect(
171	  "mobile expo build",
172	  pick("mobile", { ...base, platforms: "cross", mobileOffline: "no" }, "Build & distribution"),
173	  "Expo EAS",
174	);
175	// Native build must not be Expo EAS
176	expect(
177	  "mobile native build",
178	  pick("mobile", { ...base, platforms: "native", mobileOffline: "no" }, "Build & distribution"),
179	  "Codemagic",
180	);
181	// Web auth default for a JS/TS team is Better Auth, not Auth.js
182	expect(
183	  "web auth default",
184	  pick("web", { ...base, webRender: "app", realtime: "no", priority: "scale" }, "Authentication"),
185	  "Better Auth",
186	);
187	// Offline-first mobile (not speed) gets a local-first sync engine
188	expect(
189	  "mobile offline-first db",
190	  pick("mobile", { ...base, platforms: "cross", mobileOffline: "yes", priority: "scale" }, "Database"),
191	  "PowerSync",
192	);
193	
194	console.log("\n" + (problems === 0 ? "RESULT: ✓ no problems" : `RESULT: ✗ ${problems} problem(s)`));
195	process.exit(problems === 0 ? 0 : 1);
