content.content:
1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useState } from "react";
4	import { CATEGORIES_META, QUESTIONS } from "@/lib/questions";
5	import {
6	  recommend,
7	  recommendationToText,
8	  recommendationToMarkdown,
9	  scaffoldCommands,
10	} from "@/lib/engine";
11	import { decodeState, encodeState } from "@/lib/share";
12	import type { Answers, CategoryId, Question } from "@/lib/types";
13	
14	type Phase = "intro" | "quiz" | "result";
15	type Theme = "dark" | "light";
16	
17	function questionsFor(category: CategoryId | null): Question[] {
18	  if (!category) return [];
19	  return QUESTIONS.filter(
20	    (q) => q.appliesTo === "all" || q.appliesTo.includes(category),
21	  );
22	}
23	
24	export default function Advisor() {
25	  const [phase, setPhase] = useState<Phase>("intro");
26	  const [category, setCategory] = useState<CategoryId | null>(null);
27	  const [answers, setAnswers] = useState<Answers>({});
28	  const [step, setStep] = useState(0);
29	  const [copiedKey, setCopiedKey] = useState<string | null>(null);
30	  const [theme, setTheme] = useState<Theme>("dark");
31	
32	  const questions = useMemo(() => questionsFor(category), [category]);
33	
34	  const recommendation = useMemo(() => {
35	    if (phase !== "result" || !category) return null;
36	    return recommend(category, answers);
37	  }, [phase, category, answers]);
38	
39	  /* ---- Theme: load + persist ---- */
40	  useEffect(() => {
41	    const saved = localStorage.getItem("tsa-theme");
42	    const initial: Theme =
43	      saved === "light" || saved === "dark"
44	        ? saved
45	        : window.matchMedia?.("(prefers-color-scheme: light)").matches
46	          ? "light"
47	          : "dark";
48	    setTheme(initial);
49	  }, []);
50	  useEffect(() => {
51	    document.documentElement.setAttribute("data-theme", theme);
52	    localStorage.setItem("tsa-theme", theme);
53	  }, [theme]);
54	
55	  /* ---- Restore state from a shared URL on first load ---- */
56	  useEffect(() => {
57	    const m = window.location.hash.match(/[#&]s=([^&]+)/);
58	    if (!m) return;
59	    const decoded = decodeState(m[1]);
60	    if (!decoded || !CATEGORIES_META.some((c) => c.id === decoded.category)) return;
61	    const qs = questionsFor(decoded.category);
62	    setCategory(decoded.category);
63	    setAnswers(decoded.answers);
64	    if (qs.every((q) => decoded.answers[q.id])) {
65	      setPhase("result");
66	    } else {
67	      const firstUnanswered = qs.findIndex((q) => !decoded.answers[q.id]);
68	      setStep(firstUnanswered < 0 ? 0 : firstUnanswered);
69	      setPhase("quiz");
70	    }
71	    // eslint-disable-next-line react-hooks/exhaustive-deps
72	  }, []);
73	
74	  /* ---- Keep the URL in sync once we have a result ---- */
75	  useEffect(() => {
76	    if (phase === "result" && category) {
77	      const token = encodeState({ category, answers });
78	      window.history.replaceState(null, "", `#s=${token}`);
79	    }
80	  }, [phase, category, answers]);
81	
82	  const startCategory = useCallback((id: CategoryId) => {
83	    setCategory(id);
84	    setAnswers({});
85	    setStep(0);
86	    setPhase("quiz");
87	  }, []);
88	
89	  const choose = useCallback(
90	    (questionId: string, optionId: string) => {
91	      const qs = questionsFor(category);
92	      setAnswers((prev) => ({ ...prev, [questionId]: optionId }));
93	      if (step < qs.length - 1) setStep(step + 1);
94	      else setPhase("result");
95	    },
96	    [category, step],
97	  );
98	
99	  const back = useCallback(() => {
100	    if (phase === "result") {
101	      setPhase("quiz");
102	      setStep(Math.max(0, questionsFor(category).length - 1));
103	      return;
104	    }
105	    if (step === 0) {
106	      setPhase("intro");
107	      setCategory(null);
108	      return;
109	    }
110	    setStep(step - 1);
111	  }, [phase, step, category]);
112	
113	  const restart = useCallback(() => {
114	    setPhase("intro");
115	    setCategory(null);
116	    setAnswers({});
117	    setStep(0);
118	    setCopiedKey(null);
119	    window.history.replaceState(null, "", window.location.pathname + window.location.search);
120	  }, []);
121	
122	  const jumpTo = useCallback((index: number) => {
123	    setPhase("quiz");
124	    setStep(index);
125	  }, []);
126	
127	  const copy = useCallback(async (text: string, key: string) => {
128	    try {
129	      await navigator.clipboard.writeText(text);
130	      setCopiedKey(key);
131	      setTimeout(() => setCopiedKey(null), 1800);
132	    } catch {
133	      /* clipboard blocked — ignore */
134	    }
135	  }, []);
136	
137	  /* ---- Keyboard navigation during the quiz ---- */
138	  useEffect(() => {
139	    if (phase !== "quiz") return;
140	    const q = questions[step];
141	    if (!q) return;
142	    function onKey(e: KeyboardEvent) {
143	      if (e.key === "Backspace") {
144	        e.preventDefault();
145	        back();
146	        return;
147	      }
148	      const n = Number(e.key);
149	      if (Number.isInteger(n) && n >= 1 && n <= q!.options.length) {
150	        choose(q!.id, q!.options[n - 1].id);
151	      }
152	    }
153	    window.addEventListener("keydown", onKey);
154	    return () => window.removeEventListener("keydown", onKey);
155	  }, [phase, step, questions, choose, back]);
156	
157	  return (
158	    <main className="shell">
159	      <header className="topbar">
160	        <button className="brand" onClick={restart} aria-label="TechStack Advisor home">
161	          <span className="brand-mark">⚙︎</span>
162	          <span className="brand-name">TechStack Advisor</span>
163	        </button>
164	        <div className="topbar-actions">
165	          <button
166	            className="ghost icon-btn"
167	            onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
168	            aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} theme`}
169	            title="Toggle theme"
170	          >
171	            {theme === "dark" ? "☀︎" : "☾"}
172	          </button>
173	          {phase !== "intro" && (
174	            <button className="ghost" onClick={restart}>
175	              Start over
176	            </button>
177	          )}
178	        </div>
179	      </header>
180	
181	      {phase === "intro" && <Intro onPick={startCategory} />}
182	
183	      {phase === "quiz" && questions[step] && (
184	        <Quiz
185	          total={questions.length}
186	          step={step}
187	          question={questions[step]}
188	          selected={answers[questions[step].id]}
189	          onChoose={choose}
190	          onBack={back}
191	        />
192	      )}
193	
194	      {phase === "result" && recommendation && category && (
195	        <Result
196	          rec={recommendation}
197	          category={category}
198	          answers={answers}
199	          copiedKey={copiedKey}
200	          onCopy={copy}
201	          onBack={back}
202	          onRestart={restart}
203	          onJump={jumpTo}
204	        />
205	      )}
206	
207	      <footer className="footnote">
208	        Recommendations are a starting point, not gospel — your context always wins.
209	      </footer>
210	    </main>
211	  );
212	}
213	
214	/* ------------------------------- Intro ------------------------------- */
215	
216	function Intro({ onPick }: { onPick: (id: CategoryId) => void }) {
217	  return (
218	    <section className="intro">
219	      <div className="hero">
220	        <p className="eyebrow">Pick a starting point</p>
221	        <h1>
222	          Find the right <span className="grad">tech stack</span> for what
223	          you&apos;re building.
224	        </h1>
225	        <p className="lede">
226	          Answer a handful of questions about your project and constraints.
227	          We&apos;ll recommend a complete, opinionated stack — explaining every
228	          choice, with strengths, trade-offs, and a command to get started.
229	        </p>
230	      </div>
231	
232	      <div className="cat-grid">
233	        {CATEGORIES_META.map((c) => (
234	          <button key={c.id} className="cat-card" onClick={() => onPick(c.id)}>
235	            <span className="cat-emoji" aria-hidden>
236	              {c.emoji}
237	            </span>
238	            <span className="cat-label">{c.label}</span>
239	            <span className="cat-tag">{c.tagline}</span>
240	          </button>
241	        ))}
242	      </div>
243	
244	      <p className="methodology">
245	        100% rule-based and offline — no AI call, no API key. Every pick comes
246	        from a transparent scoring engine you can read and tweak.
247	      </p>
248	    </section>
249	  );
250	}
251	
252	/* -------------------------------- Quiz ------------------------------- */
253	
254	function Quiz({
255	  total,
256	  step,
257	  question,
258	  selected,
259	  onChoose,
260	  onBack,
261	}: {
262	  total: number;
263	  step: number;
264	  question: Question;
265	  selected?: string;
266	  onChoose: (qid: string, oid: string) => void;
267	  onBack: () => void;
268	}) {
269	  const progress = Math.round((step / total) * 100);
270	
271	  return (
272	    <section className="quiz">
273	      <div className="progress-row">
274	        <button className="ghost back" onClick={onBack}>
275	          ← Back
276	        </button>
277	        <span className="counter">
278	          Question {step + 1} of {total}
279	        </span>
280	      </div>
281	      <div className="progress" aria-hidden>
282	        <div className="progress-fill" style={{ width: `${progress}%` }} />
283	      </div>
284	
285	      <div className="q-head">
286	        <h2>{question.title}</h2>
287	        {question.subtitle && <p className="q-sub">{question.subtitle}</p>}
288	      </div>
289	
290	      <div className="options">
291	        {question.options.map((opt, i) => (
292	          <button
293	            key={opt.id}
294	            className={`option ${selected === opt.id ? "selected" : ""}`}
295	            onClick={() => onChoose(question.id, opt.id)}
296	          >
297	            <span className="opt-num" aria-hidden>
298	              {i + 1}
299	            </span>
300	            <span className="opt-body">
301	              <span className="option-main">{opt.label}</span>
302	              {opt.hint && <span className="option-hint">{opt.hint}</span>}
303	            </span>
304	          </button>
305	        ))}
306	      </div>
307	
308	      <p className="kbd-hint">
309	        Tip: press <kbd>1</kbd>–<kbd>{question.options.length}</kbd> to choose,{" "}
310	        <kbd>Backspace</kbd> to go back.
311	      </p>
312	    </section>
313	  );
314	}
315	
316	/* ------------------------------- Result ------------------------------ */
317	
318	function Result({
319	  rec,
320	  category,
321	  answers,
322	  copiedKey,
323	  onCopy,
324	  onBack,
325	  onRestart,
326	  onJump,
327	}: {
328	  rec: ReturnType<typeof recommend>;
329	  category: CategoryId;
330	  answers: Answers;
331	  copiedKey: string | null;
332	  onCopy: (text: string, key: string) => void;
333	  onBack: () => void;
334	  onRestart: () => void;
335	  onJump: (index: number) => void;
336	}) {
337	  const qs = useMemo(() => questionsFor(category), [category]);
338	  const scaffold = useMemo(() => scaffoldCommands(rec), [rec]);
339	
340	  function downloadMarkdown() {
341	    const md = recommendationToMarkdown(rec);
342	    const blob = new Blob([md], { type: "text/markdown;charset=utf-8" });
343	    const url = URL.createObjectURL(blob);
344	    const a = document.createElement("a");
345	    a.href = url;
346	    a.download = `techstack-${rec.categoryId}.md`;
347	    document.body.appendChild(a);
348	    a.click();
349	    a.remove();
350	    URL.revokeObjectURL(url);
351	  }
352	
353	  return (
354	    <section className="result">
355	      <div className="result-head">
356	        <p className="eyebrow">Your recommended stack</p>
357	        <h1>
358	          For your <span className="grad">{rec.categoryLabel.toLowerCase()}</span>
359	        </h1>
360	      </div>
361	
362	      <div className="chips">
363	        {rec.summary.map((s) => (
364	          <span key={s.layer} className="chip">
365	            <span className="chip-layer">{s.layer}</span>
366	            <span className="chip-tech">{s.tech}</span>
367	          </span>
368	        ))}
369	      </div>
370	
371	      <div className="result-actions">
372	        <button
373	          className="primary"
374	          onClick={() => onCopy(recommendationToText(rec), "stack")}
375	        >
376	          {copiedKey === "stack" ? "Copied ✓" : "Copy stack"}
377	        </button>
378	        <button
379	          className="ghost"
380	          onClick={() => onCopy(recommendationToMarkdown(rec), "md")}
381	        >
382	          {copiedKey === "md" ? "Copied ✓" : "Copy Markdown"}
383	        </button>
384	        <button className="ghost" onClick={downloadMarkdown}>
385	          Download .md
386	        </button>
387	        <button
388	          className="ghost"
389	          onClick={() => onCopy(window.location.href, "share")}
390	        >
391	          {copiedKey === "share" ? "Link copied ✓" : "Share link"}
392	        </button>
393	        <button className="ghost" onClick={onBack}>
394	          Edit answers
395	        </button>
396	        <button className="ghost" onClick={onRestart}>
397	          Start over
398	        </button>
399	      </div>
400	
401	      {/* Answer review */}
402	      <details className="review">
403	        <summary>Your answers ({qs.length})</summary>
404	        <ul className="review-list">
405	          {qs.map((q, i) => {
406	            const opt = q.options.find((o) => o.id === answers[q.id]);
407	            return (
408	              <li key={q.id}>
409	                <span className="review-q">{q.title}</span>
410	                <span className="review-a">{opt?.label ?? "—"}</span>
411	                <button className="review-edit" onClick={() => onJump(i)}>
412	                  Change
413	                </button>
414	              </li>
415	            );
416	          })}
417	        </ul>
418	      </details>
419	
420	      <div className="cards">
421	        {rec.layers.map((layer) => (
422	          <LayerCard key={layer.key} layer={layer} copiedKey={copiedKey} onCopy={onCopy} />
423	        ))}
424	      </div>
425	
426	      {scaffold.length > 0 && (
427	        <div className="getstarted">
428	          <div className="getstarted-head">
429	            <h2>Getting started</h2>
430	            <button
431	              className="ghost"
432	              onClick={() =>
433	                onCopy(
434	                  scaffold.map((s) => `# ${s.name}\n${s.command}`).join("\n\n"),
435	                  "scaffold",
436	                )
437	              }
438	            >
439	              {copiedKey === "scaffold" ? "Copied ✓" : "Copy all"}
440	            </button>
441	          </div>
442	          <pre className="codeblock">
443	            <code>
